document.querySelectorAll('form[data-print-form]').forEach((form)=>{form.addEventListener('submit',()=>{const next=form.dataset.thanks;if(next){let redirect=form.querySelector('input[name="_next"]');if(!redirect){redirect=document.createElement('input');redirect.type='hidden';redirect.name='_next';form.appendChild(redirect)}redirect.value=new URL(next,window.location.href).href}})});document.querySelectorAll('.menu-toggle').forEach((toggle)=>{toggle.addEventListener('click',()=>{const panel=document.getElementById(toggle.getAttribute('aria-controls'));const open=panel?.dataset.open==='true';if(panel){panel.dataset.open=String(!open);toggle.setAttribute('aria-expanded',String(!open))}})});document.querySelectorAll('.menu-panel a').forEach((link)=>{link.addEventListener('click',()=>{const panel=link.closest('.menu-panel');if(panel)panel.dataset.open='false'})});
